Basic dataclass example Immutable dataclass example

```python
@dataclass
class Person:
    """Basic dataclass example"""

    name: str
    age: int
    email: Optional[str] = None
    hobbies: List[str] = field(default_factory=list)

    def __post_init__(self):
        """Post-initialization validation"""
        if self.age < 0:
            raise ValueError("Age cannot be negative")

    def add_hobby(self, hobby: str):
        """Add a hobby to the person"""
        if hobby not in self.hobbies:
            self.hobbies.append(hobby)

    def get_info(self) -> str:
        """Get person information"""
        return f"{self.name} ({self.age} years old)"

@dataclass(frozen=True)
class Point:
    """Immutable dataclass example"""

    x: float
    y: float

    def distance_to(self, other: "Point") -> float:
        """Calculate distance to another point"""
        return ((self.x - other.x) ** 2 + (self.y - other.y) ** 2) ** 0.5
```

Advanced dataclass with field customization Type-hinted function example Calculate average of a list of numbers

```python
@dataclass
class Student:
    """Advanced dataclass with field customization"""

    name: str
    student_id: str
    grades: Dict[str, float] = field(default_factory=dict)
    created_at: datetime = field(default_factory=datetime.now)
    _private_field: str = field(default="private", repr=False)

    def add_grade(self, subject: str, grade: float):
        """Add a grade for a subject"""
        if not 0 <= grade <= 100:
            raise ValueError("Grade must be between 0 and 100")
        self.grades[subject] = grade

    def get_average(self) -> float:
        """Calculate average grade"""
        if not self.grades:
            return 0.0
        return sum(self.grades.values()) / len(self.grades)

    def __post_init__(self):
        """Validate student ID format"""
        if not self.student_id.startswith("STU"):
            raise ValueError("Student ID must start with 'STU'")

# ============================================================================
# TYPE HINTS EXAMPLES
