class DataProcessor(ABC):
    """Abstract base class for data processing"""

    @abstractmethod
    def process(self, data: any) -> any:
        """Process the input data"""
        pass

    @abstractmethod
    def validate(self, data: any) -> bool:
        """Validate the input data"""
        pass

    def get_info(self) -> str:
        """Get information about the processor"""
        return f"Processor: {self.__class__.__name__}"

class TextProcessor(DataProcessor):
    """Text processor implementation"""

    def process(self, data: str) -> str:
        if not self.validate(data):
            raise ValueError("Invalid text data")
        return data.upper()

    def validate(self, data: any) -> bool:
        return isinstance(data, str) and len(data) > 0

class NumberProcessor(DataProcessor):
    """Number processor implementation"""

    def process(self, data: List[float]) -> float:
        if not self.validate(data):
            raise ValueError("Invalid number data")
        return sum(data) / len(data)

    def validate(self, data: any) -> bool:
        return isinstance(data, list) and all(isinstance(x, (int, float)) for x in data)

