```python
class PersonSlots:
    """Person class using slots for memory optimization"""

    __slots__ = ["name", "age", "email"]

    def __init__(self, name: str, age: int, email: str = None):
        self.name = name
        self.age = age
        self.email = email

    def get_info(self) -> str:
        return f"{self.name} ({self.age} years old)"

class EmployeeSlots(PersonSlots):
    """Employee class inheriting slots"""

    __slots__ = ["employee_id", "salary"]

    def __init__(
        self, name: str, age: int, employee_id: str, salary: float, email: str = None
    ):
        super().__init__(name, age, email)
        self.employee_id = employee_id
        self.salary = salary

    def get_info(self) -> str:
        base_info = super().get_info()
        return f"{base_info} - Employee ID: {self.employee_id}"

# ============================================================================
# DESCRIPTORS EXAMPLES
# ============================================================================

class PositiveNumber:
    """Descriptor for positive numbers"""

    def __init__(self, name=None):
        self.name = name

    def __set_name__(self, owner, name):
        self.name = name

    def __get__(self, instance, owner):
        if instance is None:
            return self
        return instance.__dict__.get(self.name, 0)

    def __set__(self, instance, value):
        if not isinstance(value, (int, float)):
            raise TypeError(f"{self.name} must be a number")
        if value < 0:
            raise ValueError(f"{self.name} must be positive")
        instance.__dict__[self.name] = value

    def __delete__(self, instance):
        del instance.__dict__[self.name]
```

Bank account using descriptor for balance validation Descriptor that caches property values

```python
class BankAccount:
    """Bank account using descriptor for balance validation"""

    balance = PositiveNumber()

    def __init__(self, initial_balance: float = 0):
        self.balance = initial_balance

    def deposit(self, amount: float):
        """Deposit money into account"""
        if amount > 0:
            self.balance += amount
            return f"Deposited ${amount}. New balance: ${self.balance}"
        else:
            raise ValueError("Deposit amount must be positive")

    def withdraw(self, amount: float):
        """Withdraw money from account"""
        if amount > 0 and amount <= self.balance:
            self.balance -= amount
            return f"Withdrew ${amount}. New balance: ${self.balance}"
        else:
            raise ValueError("Invalid withdrawal amount")

class CachedProperty:
    """Descriptor that caches property values"""

    def __init__(self, func):
        self.func = func
        self.name = func.__name__

    def __get__(self, instance, owner):
        if instance is None:
            return self

        # Check if value is cached
        cache_name = f"_cached_{self.name}"
        if hasattr(instance, cache_name):
            return getattr(instance, cache_name)

        # Calculate and cache the value
        value = self.func(instance)
        setattr(instance, cache_name, value)
        return value

    def __set__(self, instance, value):
        # Allow setting the cached value directly
        cache_name = f"_cached_{self.name}"
        setattr(instance, cache_name, value)

    def __delete__(self, instance):
        # Clear the cache
        cache_name = f"_cached_{self.name}"
        if hasattr(instance, cache_name):
            delattr(instance, cache_name)
