@dataclass
class Book:
    """Book dataclass with validation"""

    title: str
    author: str
    isbn: str
    publication_year: int
    price: float = field(default=0.0)
    available: bool = field(default=True)

    def __post_init__(self):
        """Validate book data"""
        if self.publication_year < 1800 or self.publication_year > datetime.now().year:
            raise ValueError("Invalid publication year")
        if self.price < 0:
            raise ValueError("Price cannot be negative")
        if not self.isbn.replace("-", "").replace(" ", "").isdigit():
            raise ValueError("Invalid ISBN format")

@dataclass
class LibraryMember:
    """Library member with borrowing history"""

    member_id: str
    name: str
    email: str
    borrowed_books: List[str] = field(default_factory=list)
    membership_date: datetime = field(default_factory=datetime.now)

    def borrow_book(self, book_isbn: str) -> bool:
        """Borrow a book"""
        if book_isbn not in self.borrowed_books:
            self.borrowed_books.append(book_isbn)
            return True
        return False

    def return_book(self, book_isbn: str) -> bool:
        """Return a book"""
        if book_isbn in self.borrowed_books:
            self.borrowed_books.remove(book_isbn)
            return True
        return False
```

Library management system using multiple Python features

```python
class Library:
    """Library management system using multiple Python features"""

    def __init__(self):
        self.books: Dict[str, Book] = {}
        self.members: Dict[str, LibraryMember] = {}

    def add_book(self, book: Book) -> None:
        """Add a book to the library"""
        self.books[book.isbn] = book

    def add_member(self, member: LibraryMember) -> None:
        """Add a member to the library"""
        self.members[member.member_id] = member

    def borrow_book(self, member_id: str, book_isbn: str) -> bool:
        """Process book borrowing"""
        if member_id not in self.members:
            raise ValueError("Member not found")
        if book_isbn not in self.books:
            raise ValueError("Book not found")

        book = self.books[book_isbn]
        member = self.members[member_id]

        if not book.available:
            return False

        if member.borrow_book(book_isbn):
            book.available = False
            return True
        return False

    def return_book(self, member_id: str, book_isbn: str) -> bool:
        """Process book return"""
        if member_id not in self.members:
            raise ValueError("Member not found")
        if book_isbn not in self.books:
            raise ValueError("Book not found")

        book = self.books[book_isbn]
        member = self.members[member_id]

        if member.return_book(book_isbn):
            book.available = True
            return True
        return False

    def get_available_books(self) -> List[Book]:
        """Get list of available books"""
        return [book for book in self.books.values() if book.available]

    def get_member_books(self, member_id: str) -> List[Book]:
        """Get books borrowed by a member"""
        if member_id not in self.members:
            raise ValueError("Member not found")

        member = self.members[member_id]
        return [
            self.books[isbn] for isbn in member.borrowed_books if isbn in self.books
        ]

